// React for windows: `import { windowType, useWindow } from 'tilr/react'`. The core itself has no
// React; a window type that renders with it imports this module, which mounts the component into
// the element the layout hands over. The page runs one React (the import map's 'react'): a plugin
// that bundles its own (webamp does) is fine too, it just does not use this module.
//
// A plugin that is one window type is one line:
//
//   export default windowType({ id: 'notes', component: Notes, defaultConfig: { text: '' } })
//
// `Notes` gets `win` (the WindowHandle: config, mode, rect, the requests) as a prop, and may call
// `useWindow()` anywhere below to read it and re-render on every change of the layout.
import { createContext, useContext, useEffect, useMemo, useReducer, useSyncExternalStore } from 'react'
import type { ComponentType, ReactElement, ReactNode } from 'react'
import { createRoot } from 'react-dom/client'
import { sameSelection } from '../selection.js'
import type { Context } from 'cordis'
import type { PluginMeta, TilrPluginObject, WindowField, WindowHandle, WindowType } from 'tilr'

/** What a window component receives. */
export interface WindowProps<C = unknown> {
  win: WindowHandle<C>
}

interface Scope {
  ctx: Context
  win: WindowHandle
}

const WindowScope = createContext<Scope | null>(null)

/**
 * Renders `element` into `host` as a React root and returns the undo: the `mount` of a
 * WindowType written by hand (`ctx.windows.register('x', { mount: (host, win) => mount(host, <X win={win} />) })`).
 * The unmount is deferred a microtask: the layout calls it from an effect of its own React tree,
 * where unmounting another root synchronously is refused.
 */
export function mount(host: HTMLElement, element: ReactNode): () => void {
  const root = createRoot(host)
  root.render(element)
  return () => { queueMicrotask(() => root.unmount()) }
}

/** The current window. With fields, re-renders only when selected values change.
 * Without fields, keeps the legacy subscription to every layout change. */
export function useWindow<C = unknown>(fields?: readonly WindowField[]): WindowHandle<C> {
  const scope = useContext(WindowScope)
  if (!scope) throw new Error('useWindow(): not inside a window (windowType() or windowRoot())')
  const [, bump] = useReducer((n: number) => n + 1, 0)
  const key = fields?.join(',')
  useEffect(() => key === undefined ? scope.win.subscribe(bump) : undefined, [scope.win, key])
  const source = useMemo(() => {
    const fields = key?.split(',').filter(Boolean) as WindowField[] | undefined
    const read = () => fields?.map(field => scope.win[field]) ?? []
    let value = read()
    return {
      subscribe: (notify: () => void) => fields ? scope.win.subscribe(notify, fields) : () => {},
      getSnapshot: () => {
        const next = read()
        if (!sameSelection(value, next)) value = next
        return value
      },
    }
  }, [scope.win, key])
  useSyncExternalStore(source.subscribe, source.getSnapshot)
  return scope.win as WindowHandle<C>
}

/** A selected window field with a cached snapshot. Configs must be replaced rather than
 * mutated. Older providers may broadcast, but equal snapshots still skip React updates. */
export function useWindowField<K extends WindowField>(field: K): WindowHandle[K] {
  const scope = useContext(WindowScope)
  if (!scope) throw new Error('useWindowField(): not inside a window')
  const source = useMemo(() => {
    const win = scope.win
    let value = win[field]
    return {
      subscribe: (notify: () => void) => win.subscribe(notify, [field]),
      getSnapshot: () => {
        const next = win[field]
        if (!sameSelection(value, next)) value = next
        return value
      },
    }
  }, [scope.win, field])
  return useSyncExternalStore(source.subscribe, source.getSnapshot)
}

/** The cordis context of the plugin that registered the window's type (`ctx.on`, services it injected). */
export function useCtx(): Context {
  const scope = useContext(WindowScope)
  if (!scope) throw new Error('useCtx(): not inside a window (windowType() or windowRoot())')
  return scope.ctx
}

/** The element a window type's `mount` renders, so that `useWindow()` works below it. */
export function windowRoot(ctx: Context, win: WindowHandle, children: ReactNode): ReactElement {
  return <WindowScope.Provider value={{ ctx, win }}>{children}</WindowScope.Provider>
}

/** `windowType()`'s argument: the WindowType minus `mount`, the component, the plugin's metadata. */
export interface WindowTypeOptions<C> extends Omit<WindowType<C>, 'mount'>, Pick<PluginMeta, 'author' | 'tags' | 'version' | 'api' | 'requires'> {
  /** The type's name, and the plugin's. */
  id: string
  component: ComponentType<WindowProps<C>>
}

/** A plugin that registers one window type drawn by a React component. */
export function windowType<C = undefined>(options: WindowTypeOptions<C>): TilrPluginObject {
  const { id, component: Component, author, tags, version, api, requires, ...type } = options
  return {
    name: id,
    author,
    tags,
    version,
    api,
    requires,
    inject: ['windows'],
    apply(ctx) {
      ctx.windows.register<C>(id, {
        ...type,
        mount(host, win) {
          return mount(host, windowRoot(ctx, win, <Component win={win} />))
        },
      })
    },
  }
}
